#!/bin/zsh
set -euo pipefail
native_dir="${0:A:h}"
mkdir -p "$native_dir/build"
swiftc -swift-version 5 -parse-as-library -O -framework CoreText -framework CoreGraphics -framework PDFKit -lsqlite3 "$native_dir/NativeOperationalAssets.swift" "$native_dir/NativeDatabase.swift" "$native_dir/MailReview.swift" "$native_dir/CRMModules.swift" "$native_dir/InvoiceModules.swift" "$native_dir/OrderModules.swift" "$native_dir/CatalogModules.swift" "$native_dir/LineItemModules.swift" "$native_dir/LineItemMath.swift" "$native_dir/CRMLineItems.swift" "$native_dir/CRMCatalog.swift" "$native_dir/ProductCSV.swift" "$native_dir/PricingEngine.swift" "$native_dir/InvoiceMath.swift" "$native_dir/CRMService.swift" "$native_dir/CRMRelationships.swift" "$native_dir/OrderWorkflow.swift" "$native_dir/OrderDraftStore.swift" "$native_dir/CRMOrders.swift" "$native_dir/InvoiceWorkflow.swift" "$native_dir/InvoiceDraftStore.swift" "$native_dir/CRMInvoices.swift" "$native_dir/CRMInvoiceSettings.swift" "$native_dir/InvoiceFXClient.swift" "$native_dir/InvoicePDF.swift" "$native_dir/CRMInvoicePDF.swift" "$native_dir/InvoicePDFTests.swift" -o "$native_dir/build/InvoicePDFTests"
"$native_dir/build/InvoicePDFTests" "$native_dir" "$native_dir/../artifacts/native-invoice-pdf/請求書-表示検証.pdf"
